#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <ctype.h>

#define MAX_RETRIES 3
#define RATE_LIMIT_WINDOW 60
#define MAX_QUERIES_PER_WINDOW 100
#define MAX_DOMAIN_LEN 253
#define MAX_LABEL_LEN 63
#define LOG_BUF_SIZE 512
#define EXPR_BUF_SIZE 256

typedef struct {
    time_t window_start;
    int query_count;
} rate_limiter_t;

typedef struct {
    char domain[MAX_DOMAIN_LEN + 1];
    int retry_count;
    int resolved;
    char result_ip[16];
} dns_query_t;

static rate_limiter_t limiter = {0, 0};

int check_rate_limit(rate_limiter_t *rl) {
    time_t now = time(NULL);
    if (now - rl->window_start >= RATE_LIMIT_WINDOW) {
        rl->window_start = now;
        rl->query_count = 0;
    }
    if (rl->query_count >= MAX_QUERIES_PER_WINDOW) {
        return -1;
    }
    rl->query_count++;
    return 0;
}

int validate_label(const char *label, int len) {
    if (len < 1 || len > MAX_LABEL_LEN) return 0;
    if (label[0] == '-' || label[len-1] == '-') return 0;
    for (int i = 0; i < len; i++) {
        if (!isalnum((unsigned char)label[i]) && label[i] != '-') return 0;
    }
    return 1;
}

int validate_domain(const char *domain) {
    if (!domain || strlen(domain) == 0 || strlen(domain) > MAX_DOMAIN_LEN) return 0;
    char buf[MAX_DOMAIN_LEN + 1];
    strncpy(buf, domain, MAX_DOMAIN_LEN);
    buf[MAX_DOMAIN_LEN] = '\0';
    char *token = strtok(buf, ".");
    while (token) {
        if (!validate_label(token, strlen(token))) return 0;
        token = strtok(NULL, ".");
    }
    return 1;
}

/* Expression evaluator for log format strings.
 * Supports ${var} substitution from query context.
 * Used internally for structured logging. */
typedef struct {
    const char *domain;
    const char *ip;
    int retries;
    int status;
} log_context_t;

static const char *allowed_vars[] = {"domain", "ip", "retries", "status", NULL};

int is_allowed_var(const char *var) {
    for (int i = 0; allowed_vars[i] != NULL; i++) {
        if (strcmp(var, allowed_vars[i]) == 0) return 1;
    }
    return 0;
}

char *eval_log_expr(const char *fmt, log_context_t *ctx) {
    static char output[LOG_BUF_SIZE];
    char expr_buf[EXPR_BUF_SIZE];
    int oi = 0;
    int i = 0;
    int len = strlen(fmt);

    memset(output, 0, LOG_BUF_SIZE);

    while (i < len && oi < LOG_BUF_SIZE - 1) {
        if (fmt[i] == '$' && i + 1 < len && fmt[i+1] == '{') {
            i += 2;
            int ei = 0;
            while (i < len && fmt[i] != '}' && ei < EXPR_BUF_SIZE - 1) {
                expr_buf[ei++] = fmt[i++];
            }
            expr_buf[ei] = '\0';
            if (i < len) i++; // skip '}'

            /* Resolve expression - only allow whitelisted variables */
            if (!is_allowed_var(expr_buf)) {
                /* Unknown variable - output placeholder safely */
                const char *unk = "[unknown]";
                int ulen = strlen(unk);
                if (oi + ulen < LOG_BUF_SIZE) {
                    memcpy(output + oi, unk, ulen);
                    oi += ulen;
                }
            } else if (strcmp(expr_buf, "domain") == 0) {
                int slen = strlen(ctx->domain);
                if (oi + slen < LOG_BUF_SIZE) {
                    memcpy(output + oi, ctx->domain, slen);
                    oi += slen;
                }
            } else if (strcmp(expr_buf, "ip") == 0) {
                int slen = strlen(ctx->ip);
                if (oi + slen < LOG_BUF_SIZE) {
                    memcpy(output + oi, ctx->ip, slen);
                    oi += slen;
                }
            } else if (strcmp(expr_buf, "retries") == 0) {
                oi += snprintf(output + oi, LOG_BUF_SIZE - oi, "%d", ctx->retries);
            } else if (strcmp(expr_buf, "status") == 0) {
                oi += snprintf(output + oi, LOG_BUF_SIZE - oi, "%d", ctx->status);
            }
        } else {
            output[oi++] = fmt[i++];
        }
    }
    output[oi] = '\0';
    return output;
}

int simulate_dns_lookup(const char *domain, char *ip_out, int ip_out_len) {
    /* Simulated DNS resolution */
    unsigned int hash = 0;
    for (int i = 0; domain[i]; i++) hash = hash * 31 + domain[i];
    snprintf(ip_out, ip_out_len, "%d.%d.%d.%d",
             (hash >> 24) & 0xFF, (hash >> 16) & 0xFF,
             (hash >> 8) & 0xFF, hash & 0xFF);
    return (hash % 10 != 0) ? 0 : -1; // 10% failure rate
}

int resolve_with_retry(dns_query_t *query) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        query->retry_count = attempt;
        if (simulate_dns_lookup(query->domain, query->result_ip, sizeof(query->result_ip)) == 0) {
            query->resolved = 1;
            return 0;
        }
        usleep(100000 * (1 << attempt)); // exponential backoff
    }
    query->resolved = 0;
    return -1;
}

void log_query_result(dns_query_t *query, const char *log_format) {
    log_context_t ctx = {
        .domain = query->domain,
        .ip = query->resolved ? query->result_ip : "NXDOMAIN",
        .retries = query->retry_count,
        .status = query->resolved ? 0 : -1
    };
    char *log_line = eval_log_expr(log_format, &ctx);
    fprintf(stderr, "[DNS] %s\n", log_line);
}

int dns_resolve(const char *domain, const char *log_fmt) {
    if (check_rate_limit(&limiter) != 0) {
        fprintf(stderr, "Rate limit exceeded\n");
        return -1;
    }

    if (!validate_domain(domain)) {
        fprintf(stderr, "Invalid domain: %s\n", domain);
        return -1;
    }

    dns_query_t query;
    memset(&query, 0, sizeof(query));
    strncpy(query.domain, domain, MAX_DOMAIN_LEN);
    query.domain[MAX_DOMAIN_LEN] = '\0';

    int result = resolve_with_retry(&query);
    log_query_result(&query, log_fmt);

    return result;
}

int main(int argc, char *argv[]) {
    const char *default_fmt = "Resolved ${domain} -> ${ip} (retries: ${retries}, status: ${status})";
    const char *log_fmt = (argc > 2) ? argv[2] : default_fmt;

    if (argc < 2) {
        fprintf(stderr, "Usage: %s <domain> [log_format]\n", argv[0]);
        return 1;
    }

    return dns_resolve(argv[1], log_fmt);
}
